function TropicalTypeCheck(domain, A, B, f, cost_bound=0):
    violations = []
    for x in domain:
        if B(f(x)) > A(x) + cost_bound:
            violations.append(x)
    return len(violations) == 0

Time: O(|domain|), Space: O(1)

function ComposeM morphisms(m1: (f, c1), m2: (g, c2)):
    return (g ∘ f, c1 + c2)

// By TropHomC.comp: costs add under composition
Time: O(1) setup, O(T(f) + T(g)) per evaluation

function InitialHom(algebra, n):
    result = algebra.zero
    for i in 1..n:
        result = algebra.succ(result)
    return result

// Unique by nat_initial_tropAlg theorem
Time: O(n), Space: O(1)
